window.search = Object.assign(window.search, JSON.parse('{"results_options":{"limit_results":30,"teaser_word_count":30},"search_options":{"bool":"OR","expand":true,"fields":{"body":{"boost":1},"breadcrumbs":{"boost":1},"title":{"boost":2}}},"doc_urls":["index.html#альтернативная-документация-касаетсяменя","overview.html#первый-запуск-и-главная","address-list.html#выбор-адреса-по-списку","address-postcode.html#выбор-адреса-по-почтовому-индексу","address-map-text.html#карта-и-ввод-адреса-текстом","address-map-text.html#выбор-дома-на-карте","address-map-text.html#ввод-адреса-текстом","admin-setup.html#подготовка-домового-чата-администратором","admin-setup.html#добавление-бота-в-группу","admin-setup.html#выдача-прав-администратора","admin-bind.html#привязка-адреса-к-домовому-чату","address-management.html#мои-адреса-и-администрирование-чатов","address-management.html#мои-адреса","address-management.html#администрирование-чатов","join-chat.html#подключение-обычного-участника","news.html#новости-и-карта-событий","notifications.html#уведомления","help.html#помощь-и-обратная-связь"],"index":{"fields":["title","body","breadcrumbs"],"pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5","index":{"body":{"root":{"docs":{},"df":0,"5":{"docs":{},"df":0,"6":{"docs":{"0":{"tf":1.0}},"df":1}},"7":{"docs":{},"df":0,"6":{"docs":{},"df":0,"3":{"docs":{"8":{"tf":1.0}},"df":1}}},"g":{"docs":{},"df":0,"e":{"docs":{},"df":0,"t":{"docs":{},"df":0,"_":{"docs":{},"df":0,"n":{"docs":{},"df":0,"o":{"docs":{},"df":0,"t":{"docs":{},"df":0,"i":{"docs":{},"df":0,"f":{"docs":{},"df":0,"i":{"docs":{"16":{"tf":1.0}},"df":1}}}}}}}}}},"m":{"docs":{},"df":0,"a":{"docs":{},"df":0,"x":{"docs":{"8":{"tf":1.4142135623730951}},"df":1}}},"p":{"docs":{},"df":0,"d":{"docs":{},"df":0,"f":{"docs":{"0":{"tf":1.0}},"df":1}}},"s":{"docs":{},"df":0,"u":{"docs":{},"df":0,"m":{"docs":{},"df":0,"m":{"docs":{},"df":0,"a":{"docs":{},"df":0,"r":{"docs":{},"df":0,"y":{"docs":{},"df":0,".":{"docs":{},"df":0,"m":{"docs":{},"df":0,"d":{"docs":{"0":{"tf":1.0}},"df":1}}}}}}}}}}}},"breadcrumbs":{"root":{"docs":{},"df":0,"5":{"docs":{},"df":0,"6":{"docs":{"0":{"tf":1.0}},"df":1}},"7":{"docs":{},"df":0,"6":{"docs":{},"df":0,"3":{"docs":{"8":{"tf":1.0}},"df":1}}},"g":{"docs":{},"df":0,"e":{"docs":{},"df":0,"t":{"docs":{},"df":0,"_":{"docs":{},"df":0,"n":{"docs":{},"df":0,"o":{"docs":{},"df":0,"t":{"docs":{},"df":0,"i":{"docs":{},"df":0,"f":{"docs":{},"df":0,"i":{"docs":{"16":{"tf":1.0}},"df":1}}}}}}}}}},"m":{"docs":{},"df":0,"a":{"docs":{},"df":0,"x":{"docs":{"8":{"tf":1.4142135623730951}},"df":1}}},"p":{"docs":{},"df":0,"d":{"docs":{},"df":0,"f":{"docs":{"0":{"tf":1.0}},"df":1}}},"s":{"docs":{},"df":0,"u":{"docs":{},"df":0,"m":{"docs":{},"df":0,"m":{"docs":{},"df":0,"a":{"docs":{},"df":0,"r":{"docs":{},"df":0,"y":{"docs":{},"df":0,".":{"docs":{},"df":0,"m":{"docs":{},"df":0,"d":{"docs":{"0":{"tf":1.0}},"df":1}}}}}}}}}}}},"title":{"root":{"docs":{},"df":0}}},"documentStore":{"save":true,"docs":{"0":{"body":"Эта версия документации построена вокруг всех 56 экранов из переданного PDF: бота, группового чата и мини-приложения. Красные стрелки на скриншотах показывают, куда нажимать. Персональные данные и уникальные пригласительные ссылки на скриншотах скрыты. Документация охватывает весь пользовательский путь: первый запуск, четыре способа выбора адреса, подключение домового чата, работу администратора, управление адресами, новости, карту и уведомления. Начните с первого запуска, а затем переходите к нужному сценарию через SUMMARY.md.","breadcrumbs":"О документации » Альтернативная документация «КасаетсяМеня»","id":"0","title":"Альтернативная документация «КасаетсяМеня»"},"1":{"body":"После начала диалога бот кратко объясняет, что собирает новости о доме и городе, показывает события на карте и присылает важные уведомления. Для начала работы нужно указать адрес. Нажмите «Выбрать адрес». Откроется меню с четырьмя способами: выбрать адрес из списка, указать почтовый индекс, выбрать дом на карте или ввести адрес текстом. После настройки основной экран становится главной точкой навигации. Здесь отображаются сохранённые адреса, а ниже находятся кнопки новостей, адресов, администрирования чатов и помощи. Если к подключённому чату относится несколько домов, бот может сохранить сразу несколько адресов. При этом для персональной ленты рекомендуется отдельно указать свой адрес проживания через «Мои адреса». Для возврата из меню выбора адреса используйте «← Назад». Эта кнопка возвращает в предыдущий раздел, а не запускает выбор заново. Дальше можно выбрать удобный способ указания дома: по списку; по почтовому индексу; на карте или текстом.","breadcrumbs":"Первый запуск и главная » Первый запуск и главная","id":"1","title":"Первый запуск и главная"},"10":{"body":"После того как бот добавлен в группу и получил нужные права, вернитесь в личный диалог и продолжите подключение. Если выбранный адрес уже связан с доступным чатом, сервис сразу показывает этот чат. В мини-приложении нажмите на нужный чат. Проверьте адрес и название чата, затем нажмите «Подтвердить». После успешной привязки появляется экран с кнопкой «На главную». Есть и тот же сценарий в личном чате с ботом. После проверки прав бот показывает группы, к которым можно привязать выбранный адрес. Выберите группу и подтвердите действие. Бот сообщит, что адрес успешно привязан. Если подключение выполнялось через мини-приложение, отдельный экран также подтверждает успешное добавление чата. После завершения в домовом чате появляется приветственное сообщение сервиса с адресом и кнопкой «Присоединиться» для жителей. Адрес должен быть свободен от привязки к другому домовому чату. Если условия не выполнены, сначала исправьте настройки группы или выберите другой адрес.","breadcrumbs":"Привязка адреса к чату » Привязка адреса к домовому чату","id":"10","title":"Привязка адреса к домовому чату"},"11":{"body":"В сервисе есть два разных раздела: «Мои адреса» для личных адресов пользователя и «Администрирование чатов» для адресов групп, которыми вы управляете.","breadcrumbs":"Мои адреса и администрирование чатов » Мои адреса и администрирование чатов","id":"11","title":"Мои адреса и администрирование чатов"},"12":{"body":"На главной нажмите «Мои адреса». Здесь отображаются сохранённые адреса. Можно открыть существующий адрес или добавить новый. Если вы присоединились к чату, у которого несколько адресов, сервис может сохранить все адреса чата. Для персональных новостей рядом с домом добавьте собственный адрес проживания отдельно.","breadcrumbs":"Мои адреса и администрирование чатов » Мои адреса","id":"12","title":"Мои адреса"},"13":{"body":"На главной нажмите «Администрирование чатов». Бот показывает чаты, доступные для редактирования, и отдельную кнопку «Привязать чат» для подключения нового. Открыв адрес конкретного чата, администратор может удалить его из списка привязанных адресов. Если нужно подключить новый чат, нажмите «Привязать чат». После этого откроется стандартное меню выбора адреса с теми же четырьмя способами, что и при первом запуске.","breadcrumbs":"Мои адреса и администрирование чатов » Администрирование чатов","id":"13","title":"Администрирование чатов"},"14":{"body":"После того как администратор связал домовой чат с адресом, в группе появляется сообщение сервиса. Жителю не нужно повторять административную настройку. Нажмите «Присоединиться» под сообщением в домовом чате. Бот сохранит адреса этого чата в «Мои адреса». Если у чата несколько домов, будут добавлены все связанные адреса. После этого можно вернуться на главную и пользоваться новостями, картой и уведомлениями. Для более точной персональной ленты укажите собственный адрес проживания через «Мои адреса» → «Добавить адрес».","breadcrumbs":"Подключение обычного участника » Подключение обычного участника","id":"14","title":"Подключение обычного участника"},"15":{"body":"Кнопка «Посмотреть новости рядом» открывает мини-приложение с двумя лентами: новости рядом с выбранным адресом и общегородские новости. Во вкладке «Новости рядом» показываются события, которые относятся к ближайшей территории. Во вкладке «Новости города» можно переключиться на события более широкого масштаба. На карте события отмечены маркерами. Карточка выбранного события показывает заголовок, место и краткое описание. Карта умеет фокусироваться на вашем доме. Кнопка «Назад» возвращает к предыдущему экрану, а «К дому» переводит карту к сохранённому адресу. Карточку события внизу карты можно сворачивать, чтобы освободить место для просмотра маркеров.","breadcrumbs":"Новости и карта событий » Новости и карта событий","id":"15","title":"Новости и карта событий"},"16":{"body":"Сервис присылает отдельные уведомления о важных событиях. Для демонстрации того же интерфейса можно использовать команду /get_notify. Сначала уведомление приходит в компактном виде: краткий текст, ссылка с объяснением механики и две кнопки - «Подробнее» и «Увидел». Нажмите «Подробнее», чтобы развернуть сообщение. В расширенной версии отображается полный текст и карточка источника. Кнопка меняется на «Свернуть». Кнопка «Увидел» подтверждает просмотр уведомления. После подтверждения бот возвращает пользователя на главную страницу.","breadcrumbs":"Уведомления » Уведомления","id":"16","title":"Уведомления"},"17":{"body":"На главной странице есть отдельная кнопка «Помощь и обратная связь». Используйте её, если возник вопрос по работе сервиса или нужно сообщить о проблеме. В исходном наборе скриншотов показан только вход в этот раздел, поэтому дальнейшие экраны здесь не описаны.","breadcrumbs":"Помощь и обратная связь » Помощь и обратная связь","id":"17","title":"Помощь и обратная связь"},"2":{"body":"Способ «Выбрать адрес» удобен, когда известны район, улица и номер дома. Бот ведёт по адресу последовательно и не требует ручного ввода. Сначала выберите город. В текущем сценарии доступна Москва. После этого выберите район. Длинные списки разбиты на страницы: снизу есть стрелки перехода, номер текущей страницы и быстрые переходы на несколько страниц. Далее бот показывает улицы выбранного района. Нажмите на нужную улицу. Последний шаг - номер дома. Если домов много, список также разбивается на страницы. После выбора дома сервис показывает результат. Если к адресу уже есть доступный домовой чат, он появляется в списке и его можно выбрать для привязки. Если чат ещё не подключён, сервис предлагает два варианта: скопировать приглашение для администратора или продолжить подключение самостоятельно как администратор. Если вы администратор, переходите к разделу «Подготовка домового чата». Если чат уже найден, переходите к привязке адреса.","breadcrumbs":"Выбор адреса по списку » Выбор адреса по списку","id":"2","title":"Выбор адреса по списку"},"3":{"body":"Если известен шестизначный индекс, этот способ позволяет быстро сузить список улиц и домов. В меню выбора адреса нажмите «Указать почтовый индекс». Бот попросит отправить индекс обычным сообщением. Индекс не выбирает дом автоматически - он только ограничивает список подходящих адресов. После отправки индекса появится список улиц, относящихся к нему. Выберите нужную улицу. Затем выберите дом. Если список большой, используйте навигацию по страницам снизу. После выбора дома дальнейший сценарий совпадает с другими способами: сервис показывает выбранный адрес и либо предлагает существующий чат, либо помогает подключить новый.","breadcrumbs":"Выбор адреса по индексу » Выбор адреса по почтовому индексу","id":"3","title":"Выбор адреса по почтовому индексу"},"4":{"body":"","breadcrumbs":"Карта и ввод адреса текстом » Карта и ввод адреса текстом","id":"4","title":"Карта и ввод адреса текстом"},"5":{"body":"На главном экране выбора адреса нажмите «Указать на карте». В мини-приложении можно двигать карту и использовать свою геопозицию. Ниже отображаются ближайшие дома. Нажмите на подходящий адрес. Проверьте выбранный адрес и нажмите «Подтвердить адрес». Если дом выбран неверно, нажмите «Выбрать другой».","breadcrumbs":"Карта и ввод адреса текстом » Выбор дома на карте","id":"5","title":"Выбор дома на карте"},"6":{"body":"Можно не искать дом вручную. Выберите «Ввести текстом» и начните вводить улицу, дом или район. Сервис показывает подходящие варианты по мере ввода. Нажмите на нужный адрес. После выбора ещё раз проверьте адрес и подтвердите его. Оба способа приводят к одному результату: адрес сохраняется для дальнейшего подключения чата или личной ленты.","breadcrumbs":"Карта и ввод адреса текстом » Ввод адреса текстом","id":"6","title":"Ввод адреса текстом"},"7":{"body":"Если у выбранного дома ещё нет подключённого чата, сервис предлагает отправить приглашение администратору или продолжить подключение самостоятельно. Кнопка «Скопировать пригласительное сообщение» создаёт готовый текст со ссылкой на подключение. Уникальная часть ссылки на скриншотах скрыта. После копирования можно вернуться к экрану выбранного адреса и продолжить подключение из того же места. Тот же текст можно открыть в мини-приложении и скопировать оттуда. Если подключаете чат сами, выберите «Я админ чата». Бот объяснит два обязательных действия: добавить его в групповой чат и выдать право читать сообщения. После выполнения нужно вернуться в личный чат и нажать «Проверить ещё раз».","breadcrumbs":"Подготовка домового чата администратором » Подготовка домового чата администратором","id":"7","title":"Подготовка домового чата администратором"},"8":{"body":"Откройте информацию о домовом чате и нажмите «Добавить участника». В списке участников используйте поиск. Найдите «Хакатон MAX 763» и выберите бота. После выбора нажмите «Добавить в чат». MAX может спросить, показывать ли новому участнику историю чата. Для работы сервиса выберите «Показать». Если бот добавлен без нужных прав, в группе появится предупреждение.","breadcrumbs":"Подготовка домового чата администратором » Добавление бота в группу","id":"8","title":"Добавление бота в группу"},"9":{"body":"Откройте раздел «Администраторы» в настройках группы. Нажмите «Добавить администратора». Выберите бота в списке. В правах администратора обязательно включите «Читать сообщения», затем нажмите «Назначить администратором». После этого вернитесь в личный чат с ботом и продолжите привязку адреса к чату.","breadcrumbs":"Подготовка домового чата администратором » Выдача прав администратора","id":"9","title":"Выдача прав администратора"}},"docInfo":{"0":{"body":3,"breadcrumbs":0,"title":0},"1":{"body":0,"breadcrumbs":0,"title":0},"10":{"body":0,"breadcrumbs":0,"title":0},"11":{"body":0,"breadcrumbs":0,"title":0},"12":{"body":0,"breadcrumbs":0,"title":0},"13":{"body":0,"breadcrumbs":0,"title":0},"14":{"body":0,"breadcrumbs":0,"title":0},"15":{"body":0,"breadcrumbs":0,"title":0},"16":{"body":1,"breadcrumbs":0,"title":0},"17":{"body":0,"breadcrumbs":0,"title":0},"2":{"body":0,"breadcrumbs":0,"title":0},"3":{"body":0,"breadcrumbs":0,"title":0},"4":{"body":0,"breadcrumbs":0,"title":0},"5":{"body":0,"breadcrumbs":0,"title":0},"6":{"body":0,"breadcrumbs":0,"title":0},"7":{"body":0,"breadcrumbs":0,"title":0},"8":{"body":3,"breadcrumbs":0,"title":0},"9":{"body":0,"breadcrumbs":0,"title":0}},"length":18},"lang":"English"}}'));